</template>

<script setup>
import { ref, onMounted } from 'vue';
import ScrollTrigger from 'gsap/ScrollTrigger';
import gsap from 'gsap';

const cells = ref(null)

gsap.registerPlugin(ScrollTrigger)

onMounted(() => {
  let tl = gsap.timeline({
    scrollTrigger: {
      trigger: cells.value,
      start: 'top 80%',
      end: 'bottom 20%'
    }
  })
  tl.to('.cell-item', {
    background: 'transparent',
    duration: 0.01,
    stagger: {
      each: 0.01,
      from: 'random',
    } 
  })
  tl.to('.cell', {
    opacity: 1,
    duration: 0.01,
    stagger: {
      each: 0.02,
      from: 'random',
    } 
  })
  tl.from('.error-card', {
    yPercent: -15,
    opacity: 0,
    duration: 0.15,
  })
  tl.to('.cell-red', {
    fill: 'var(--color-primary)',
    duration: 0.2,
    yoyo: true,
    repeat: -1,
  }, '<')
})
</script>

<style lang="scss" scoped>
.cell {
  opacity: 0;
}

.cell-overlay-grid {
  display: grid;
  grid-template-columns: repeat(11, 1fr);
  grid-template-rows: repeat(5, 1fr);
  align-items: center;
  justify-items: center;
  align-content: center;
  justify-content: center;
  position: absolute;
  top: 0;
  z-index: 10;
  height: 100%;
  aspect-ratio: 235/124;
  max-height: 65vh;
  margin: 0 auto;
  left: 0;
  right: 0;

  .cell-item {
    width: 100%;
    height: 100%;
    border: 2px;
    border-style: dotted;
    border-color: transparent;
    transition: all .2s ease-in-out;
    background: var(--color-primary);
    aspect-ratio: 1/1;

    &:nth-child(odd):hover {
      border-color: var(--color-gray-light);
      transform: scale(1.1);
    }
  }
}

.cell {
  fill: var(--color-background);
  transition: opacity .2s ease-in-out;
  position: relative;
}
</style>